#include <iostream>
#include <vector>
class Grid {
    int rows_, cols_;
    std::vector<int> data_;
public:
    Grid(int r, int c) : rows_(r), cols_(c), data_(r*c) {}
    int& at(int r,int c) { return data_[r*cols_+c]; }
    bool try_add(const Grid& other) {
        // TODO: rifiuta forme diverse prima di modificare qualsiasi cella.
        if (rows_ != other.rows_ || cols_ != other.cols_) return false;
        // La compatibilita e nota prima del primo aggiornamento.
        for (std::size_t i=0; i<data_.size(); ++i) data_[i] += other.data_[i];
        return true;
    }
    void print() const { for (int x : data_) std::cout << x << ' '; }
};
int main() {
    int r=0,c=0,s=0,t=0;
    std::cin >> r >> c >> s >> t;
    Grid a(r,c), b(s,t);
    for(int i=0;i<r;++i) for(int j=0;j<c;++j) std::cin >> a.at(i,j);
    for(int i=0;i<s;++i) for(int j=0;j<t;++j) std::cin >> b.at(i,j);
    std::cout << a.try_add(b) << ' '; a.print();
}

