#include <memory>
#include <utility>
class SampleBlock {
    std::unique_ptr<int[]> data_;
    std::size_t size_;
public:
    explicit SampleBlock(std::size_t n)
        : data_(n ? std::make_unique<int[]>(n) : nullptr), size_(n) {}
    SampleBlock(SampleBlock&& other) noexcept
        : data_(std::move(other.data_)), size_(other.size_) {
        // TODO: trasferisci la risorsa e conserva l'invariante della sorgente.
        other.size_ = 0;
    }
    SampleBlock& operator=(SampleBlock&& other) noexcept {
        // TODO: tratta anche una destinazione gia proprietaria e il self-move.
        if (this != &other) {
            data_ = std::move(other.data_); // Rilascia anche la vecchia risorsa.
            size_ = other.size_;
            other.size_ = 0;
        }
        return *this;
    }
    const int* data() const { return data_.get(); }
    std::size_t size() const { return size_; }
};
int main() {
    std::size_t n=0,m=0;std::cin >> n >> m;
    SampleBlock a(n);const int* first=a.data();
    SampleBlock b(std::move(a));
    std::cout << a.size() << ' ' << (!a.data()) << ' '
              << b.size() << ' ' << (b.data()==first) << ' ';
    SampleBlock c(m);c=std::move(b);c=std::move(c);
    std::cout << b.size() << ' ' << (!b.data()) << ' '
              << c.size() << ' ' << (c.data()==first);
}

