#include <iostream>
#include <string>
#include <memory>
struct TextFilter {
    virtual ~TextFilter() = default;
    virtual std::string apply(const std::string&) const = 0;
};
struct MaskDigits final : TextFilter {
    std::string apply(const std::string& input) const override {
        // TODO: restituisci una copia con ogni cifra ASCII sostituita da #.
        std::string result = input;
        for (char& ch : result) {
            if (ch >= '0' && ch <= '9') ch = '#';
        }
        return result;
    }
};
int main() {
    std::string input;std::getline(std::cin,input);
    std::unique_ptr<TextFilter> filter=std::make_unique<MaskDigits>();
    const TextFilter& view=*filter;
    std::cout << view.apply(input) << '\n' << input << '\n';
}

